  "d.d6aodn": "Disinn tal-vapuri, ġenerat kompletament bl-IA.",
  "d.d92f30": "SĦANA SOLARI",
  "d.dictbg": "Fregata ta' skorta. Torrijiet tad-difiża ta' qrib fuq outriggers jarmu r-rokits mis-sema.",
  "d.dzmviz": "Assi ġenerati bl-IA jistgħu jkollhom protezzjoni limitata tad-drittijiet tal-awtur; qed nivverifikaw il-liġi.",
  "d.ei48ov": "VAPUR ARMAT",
